pub fn f(value: anytype) f64 {
    return @floatFromInt(value);
}
pub fn vector(count: usize) Vector {
    const out = alloc(f64, count);
    @memset(out, 0);
    return out;
}
fn sum(values: []const f64) f64 {
    var out: f64 = 0;
    for (values) |value| out += value;
    return out;
